function rotateByOne(arr) {
  if (arr.length <= 1) return arr;
  const last = arr[arr.length - 1];
  for (let i = arr.length - 1; i > 0; i--) {
    arr[i] = arr[i - 1];
  }
  arr[0] = last;
  return arr;
}
